import java.util.List;

/**
 * The policy base premium: the sum of the base premiums of all insured items.
 *
 * The office prices alike items as a group, so that the building-block offer can apply
 * to each group in turn; the policy base premium is the sum of those group prices.
 * Risk surcharges for individual items are not part of it -- they attach to the
 * affected item, not to the policy.
 */
public class PolicyBasePremium {

    private final AlikeItems alikeItems = new AlikeItems();
    private final ComponentBlockOffer blockOffer = new ComponentBlockOffer();

    public double forItems(List<Item> items) {
        double total = 0;
        for (List<Item> group : alikeItems.groupsIn(items)) {
            total += blockOffer.basePremiumFor(group);
        }
        return total;
    }
}
=== PolicyModifiers.java ===
/**
 * The policy-wide modifiers the office applies to a quote, as one signed adjustment.
 *
 * Unlike a risk surcharge, which attaches to the one item that carries the risk, a
 * policy-wide modifier is assessed against the policy base premium -- the sum of all
 * item base premiums. Each modifier the quote carries is assessed on its own, and the
 * policy carries the sum of their signed rates: surcharges raise the adjustment,
 * discounts lower it.
 */
public class PolicyModifiers {

    public double forPolicy(double policyBasePremium, Customer customer, int earlierContracts) {
        return policyBasePremium * totalRateFor(customer, earlierContracts);
    }

    private double totalRateFor(Customer customer, int earlierContracts) {
        double rate = 0;
        for (PolicyWideModifier modifier : PolicyWideModifier.values()) {
            if (modifier.isCarriedByQuoteFor(customer, earlierContracts)) {
                rate += modifier.rate();
            }
        }
        return rate;
    }
}
