import java.util.List;

/**
 * What the item-specific risk surcharges of a policy add up to.
 *
 * The office assesses each insured item on its own -- a curse raises the premium of the
 * cursed item, not of its harmless neighbours -- and the policy carries the sum.
 */
public class PolicyRiskSurcharges {

    private final ItemRiskSurcharge itemRiskSurcharge = new ItemRiskSurcharge();

    public double forItems(List<Item> items) {
        double total = 0;
        for (Item item : items) {
            total += itemRiskSurcharge.forItem(item);
        }
        return total;
    }
}
=== PolicyWideModifier.java ===
/**
 * A modifier the MHPCO assesses against the policy base premium as a whole, and the
 * signed rate it carries.
 *
 * The office's catalogue of policy-wide modifiers: each entry names one, says when a
 * quote carries it, and at what rate. A surcharge carries a positive rate, a discount a
 * negative one. Revising a rate or an eligibility rule is a change to one entry;
 * recognising a new modifier is a new entry.
 *
 * Eligibility is asked of the quote being assessed. Most entries answer it from the
 * customer's history, but an entry is free to ignore that history -- the office reads
 * "when does this quote carry the modifier", not "what kind of customer is this".
 *
 * Unlike a recognised risk, which attaches to the one item that carries it, these are
 * assessed against the sum of all item base premiums.
 */
public enum PolicyWideModifier {

    /**
     * Every quote is a first insurance of its items, so the office charges the initial
     * assessment on every quote, whatever the customer's history.
     */
    INITIAL_ASSESSMENT(0.10) {
        @Override
        boolean isCarriedByQuoteFor(Customer customer, int earlierContracts) {
            return true;
        }
    },

    LOYALTY_DISCOUNT(-0.20) {
        @Override
        boolean isCarriedByQuoteFor(Customer customer, int earlierContracts) {
            return customer.isLongStanding();
        }
    },

    /**
     * The office grants a discount on each contract the customer takes out after the
     * first one.
     */
    FOLLOW_UP_CONTRACT_DISCOUNT(-0.15) {
        @Override
        boolean isCarriedByQuoteFor(Customer customer, int earlierContracts) {
            return earlierContracts > 0;
        }
    };

    private final double rate;

    PolicyWideModifier(double rate) {
        this.rate = rate;
    }

    abstract boolean isCarriedByQuoteFor(Customer customer, int earlierContracts);

    double rate() {
        return rate;
    }
}
